\label{thm1.1}
Fix $N\geq2$, $R\in(0,1)$ and $\alpha\in(0,1)$. There exists $\gamma_{\mathrm{bd}}(R,N)>0$ such that, for every fixed $|\gamma|<\gamma_{\mathrm{bd}}(R,N)$ and every sufficiently small $g\in\mathcal G$, there is a unique small $f=f(g)\in\mathcal F$ for which $\Omega_g\setminus\overline{D_f}$ admits a solution of \eqref{e1.1} for some constant $Q=Q(g)>0$. The map $g\mapsto f(g)$ is smooth, and uniqueness is understood in a neighborhood of $(0,0)\in\mathcal F\times\mathcal G$. Moreover, $f(0)=0$, $Q(0)=Q_R^{\mathrm{bd}}$, and the reference solution is given by \eqref{e1.2}.

\begin{figure}[ht]
\centering
\includegraphics[width=0.7\textwidth]{1}
\caption{The nontrivial bounded domain $\Omega_g \setminus\overline{D_f}$.}
\end{figure}

\label{thm1.2}
For each $n\geq2$ and $\alpha\in(0,1)$, there exists $\gamma_{\mathrm{cyl}}(n)>0$ such that, for every fixed $|\gamma|<\gamma_{\mathrm{cyl}}(n)$, there are $R_*=R_*(n,\gamma)\in(0,1)$ and a smooth map
\[
(-\varepsilon,\varepsilon)\longrightarrow
(0,1)\times C^{2,\alpha}_{p,e}(\mathbb R),\qquad
s\longmapsto(R_s,\varphi_s),
\]
where $C^{2,\alpha}_{p,e}$ denotes the even $2\pi$-periodic H\"older space, such that $R_0=R_*$, $\varphi_0=0$, and $0<\phi_s:=R_s+\varphi_s<1$. For every $s$, there is an even, $2\pi$-periodic solution $u_s\in C^{2,\alpha}(\overline{\Omega_1^t\setminus\overline{D_{\phi_s}^t}})$ of
\begin{equation}\label{e1.6}
\left\{
\begin{array}{ll}
-\Delta u_s=\gamma &\text{in }\Omega_1^t\setminus\overline{D_{\phi_s}^t},\\
u_s=0 &\text{on }\partial\Omega_1^t,\\
u_s=1 &\text{on }\partial D_{\phi_s}^t,\\
\partial_{\mathbf n}u_s=Q_{R_s}^{\mathrm{cyl}}>0
&\text{on }\partial D_{\phi_s}^t.
\end{array}
\right.
\end{equation}
in the domain
\begin{equation}\label{e1.7}
\Omega_1^t\setminus\overline{D_{\phi_s}^t}
=\{(x,t)\in\mathbb R^n\times\mathbb R:\phi_s(t)<|x|<1\}.
\end{equation}
Moreover,
\[
\varphi_s(t)=s\cos t+s\mu_s(t),\qquad
\int_0^{2\pi}\mu_s(t)\cos t\,dt=0,\qquad \mu_0=0,
\]
where $s\mapsto\mu_s\in C^{2,\alpha}_{p,e}(\mathbb R)$ is smooth. In particular, $\phi_s$ is nonconstant for $s\ne0$. No zero-average condition is imposed on $\varphi_s$.

\begin{figure}[ht]
\centering
\includegraphics[width=0.7\textwidth]{2}
\caption{The nontrivial unbounded domain $\Omega^{t}_{1}\setminus \overline{D^{t}_{\phi_s}}$.}
\end{figure}

\label{thm:bounded-linearization}
The map $\Psi$ is smooth near $(0,0)\in\mathcal F\times\mathcal G$, and
\begin{equation}\label{e3.2}
\partial_f\Psi(0,0)[f_0]=\partial_{\mathbf n}u_f'
+\kappa_R^{\mathrm{bd}}f_0,\qquad f_0\in\mathcal F,
\end{equation}
where $u_f'$ solves \eqref{e2.7}.

Extend the normal graphs to a $C^{2,\alpha}$ diffeomorphism $\Theta_{f,g}$ of the reference annulus. The pull-back $u_{f,g}\circ\Theta_{f,g}$ solves a uniformly elliptic Dirichlet problem on $A_0$ whose coefficients depend smoothly on $(f,g)$. The Dirichlet operator is an isomorphism from the space of $C^{2,\alpha}$ functions with zero boundary values to $C^{0,\alpha}$. Smooth dependence of its inverse and Schauder estimates give a smooth solution map into $C^{2,\alpha}$, and a smooth pulled-back Neumann map into $C^{1,\alpha}$; see \cite{Gilbarg,HenrotP}.

Set $u_t=u_{tf_0,0}$. At the reference boundary, the derivative of the unit normal is tangential and $\nabla u_R$ is normal. Hence differentiating \eqref{e2.4}, we can obtain that  
\begin{equation}\label{e3.5}
\begin{aligned}
\left.\frac{d}{dt}\right|_{t=0}q_{tf_0,0}
=\left.\frac{d}{dt}\right|_{t=0}\nabla u_{tf_0,0}(x+tf_0\mathbf n)\cdot \mathbf n
&=\left(\nabla u_f'+D^2u_R f_0 \mathbf n \right)\cdot \mathbf n \\
=\partial_{\mathbf n}u_f'+u''_{R}f_0=\partial_{\mathbf n}u_f'+\kappa_R^{\mathrm{bd}}f_0,
\end{aligned}
\end{equation}
where $u'_f$ is the solution of \eqref{e2.7} (see also \cite[Theorem 3.3]{Cav}).
Since $\int_{\partial D_0}f_0=0$, the spherical average of $u_f'$ solves the radial harmonic equation with zero values at both boundaries. Therefore, $\int_{\partial D_0}\partial_{\mathbf n}u_f'=0$, and the average of the right-hand side of \eqref{e3.5} vanishes. It follows from \eqref{e2.3} and \eqref{e3.5}
that 
$$
\partial_f\Psi(0,0)[f_0]=\left.\frac{d}{dt}\right|_{t=0}q_{tf_0,0}=\partial_{\mathbf n}u_f'+\kappa_R^{\mathrm{bd}}f_0.
$$

\label{thm3.1}
For $\phi$ in a sufficiently small neighborhood of $R$ in $X$, \eqref{eq3.2} has a unique even, $2\pi$-periodic solution $u_\phi\in C^{2,\alpha}(\overline{A_R})$. The pulled-back solution and its inner Neumann trace depend smoothly on $\phi$ and are radial in $x$. At $\phi\equiv R$, the solution is $u_R(x,t)=U_R(|x|)$, where
\begin{equation}\label{eq3.6}
U_R(r)=
\begin{cases}
\dfrac{\gamma}{2n}(1-r^2)+b_R(r^{2-n}-1),&n\geq3,\\[1ex]
\dfrac{\gamma}{4}(1-r^2)+b_R\log r,&n=2,
\end{cases}
\quad
b_R=
\begin{cases}
\dfrac{1+\frac{\gamma}{2n}(R^2-1)}{R^{2-n}-1},&n\geq3,\\[1ex]
\dfrac{1+\frac{\gamma}{4}(R^2-1)}{\log R},&n=2.
\end{cases}
\end{equation}

\label{lem3.2}
The map $\phi\mapsto\partial_{\nu_\phi}u^\phi(Re_1,\cdot)$ is smooth into $Y$, and
\begin{equation}\label{eq3.11}
\left[D_\phi\big|_{\phi=R}\,
\partial_{\nu_\phi}u^\phi(Re_1,\cdot)\right]\psi
=-\kappa_R^{\mathrm{cyl}}\psi.
\end{equation}

\label{thm3.3}
The linearized operator $L_R=D_\varphi H(R,0):X\to Y$ is
\begin{equation}\label{eq3.19}
L_R\psi=Q_R^{\mathrm{cyl}}\partial_\nu w_{\psi,R}(Re_1,\cdot)
-\kappa_R^{\mathrm{cyl}}\psi,
\end{equation}
where $\nu=(-x/|x|,0)$ on $|x|=R$ and $w_{\psi,R}$ is the unique even, periodic solution of
\begin{equation}\label{eq3.20}
\left\{
\begin{array}{ll}
\Delta_xw_{\psi,R}+\partial_{tt}w_{\psi,R}=0 &\text{in }A_R,\\
w_{\psi,R}=\psi(t) &\text{on }|x|=R,\\
w_{\psi,R}=0 &\text{on }|x|=1.
\end{array}
\right.
\end{equation}

\label{thm3.4}
For every $n\geq2$, there is $\gamma_{\mathrm{cyl}}(n)>0$ and a smooth radius $R_*=R_*(n,\gamma)\in(0,1)$ for $|\gamma|<\gamma_{\mathrm{cyl}}(n)$ such that
\begin{equation}\label{eq:cyl-simple-zero}
\Lambda_1(R_*,\gamma)=0,\qquad
\partial_R\Lambda_1(R_*,\gamma)\ne0,\qquad
Q_{R_*}^{\mathrm{cyl}}>0.
\end{equation}
Moreover, $\Lambda_0(R_*,\gamma)<0$ and $\Lambda_k(R_*,\gamma)>0$ for all $k\geq2$.
